import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import ast, glob, re, subprocess
names = ['check_map', 'repeats_detector', 'registry_problems', 'trigger_problems', 'stored_pack', 'forget_audits', 'lead_passage', 'ci_status', 'read_pipeline', 'ConfigError']
src = {f: open(f, encoding='utf-8').read() for f in glob.glob('_tools/*.py')}
extra = subprocess.run(['git', 'grep', '-h', '-I', '-e', '.', '--', '.claude', 'skills', 'agents', '.githooks', 'otel'], capture_output=True, text=True).stdout
words = re.findall(r'[A-Za-z_][A-Za-z0-9_]*', '\n'.join(src.values()) + extra)
from collections import Counter
c = Counter(words)
left = []
for f, s in src.items():
    for n in ast.parse(s).body:
        if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name in names and c[n.name] <= 1:
            left.append(f + ':' + n.name)
print('defined and referenced nowhere else:', left)
sys.exit(1 if left else 0)
